}

export async function setReminderAssignmentEnabled({
  assignment,
  assignments,
  enabled,
  locale,
  now,
  statements,
}: {
  assignment: ReminderAssignment;
  assignments: readonly ReminderAssignment[];
  enabled: boolean;
  locale: AppLocale;
