  return snapshot.matches(REMINDER_STATES.EDITOR) || snapshot.matches(REMINDER_STATES.SAVING)
    ? <Editor /> : <Library />;
}

afterEach(async () => {
  actor?.stop();
  actor = undefined;
  if (database) {
    await database.query('DELETE reminder_assignment');
    database = undefined;
  }
  const scheduled = await Notifications.getAllScheduledNotificationsAsync();
  await Promise.all(scheduled.filter((request) => request.content.data?.['owner'] === REMINDER_NOTIFICATION_OWNER)
